    def change_his_to_forward(self, security, data, exrights_data, start, end):
        if len(data) == 0:
            return data
        else:
            firstdate = list(data.index)[0].tz_localize(None).to_pydatetime().strftime('%Y%m%d')
            if start != firstdate:
                start = firstdate
            if len(start) > 8:
                start = start[:8]
            if len(end) > 8:
                end = end[:8]
            startDateIndex = qdt.datetime.strptime(start, '%Y%m%d').strftime('%Y-%m-%d 00:00:00')
            endDateIndex = qdt.datetime.strptime(end, '%Y%m%d').strftime('%Y-%m-%d 00:00:00')
            fields = ['open', 'close', 'high', 'low', 'price']
            series = exrights_data[security]
            if series.empty:
                return data
            elif series[startDateIndex:].empty:
                return data
            elif startDateIndex == endDateIndex:
                n = list(series[startDateIndex:].index)[0]
                if n == startDateIndex:
                    if len(series[startDateIndex:].index) > 1:
                        n = list(series[startDateIndex:].index)[1]
                    else:
                        return data
                data = data * float(series.loc[n, 'exer_forward_a']) + float(series.loc[n, 'exer_forward_b'])
                return data
            else:
                preindex = None
                tmpdata = None
                if len(series[startDateIndex:].index) > 0:
                    tmpstartindex = series[startDateIndex:].index[0]
                else:
                    tmpstartindex = None
            if len(series[endDateIndex:].index) > 1:
                tmpendindex = series[endDateIndex:].index[1]
            else:
                tmpendindex = None
            for n in list(series[tmpstartindex:tmpendindex].index):
                if data[preindex:n].empty:
                    continue
                elif len(data[preindex:n].index) == 1:
                    if list(data[preindex:n].index)[0].tz_localize(None) == pandas.Timestamp(qdt.datetime.strptime(start, '%Y%m%d')):
                        continue
                    elif list(data[preindex:n].index)[0].tz_localize(None) == pandas.Timestamp(qdt.datetime.strptime(end, '%Y%m%d')):
                        if preindex is None:
                            tmpdata = data[preindex:n]
                            if tmpdata[n:].empty:
                                data.loc[preindex:n, fields] = data[preindex:n][fields] * float(series.loc[n, 'exer_forward_a']) + float(series.loc[n, 'exer_forward_b'])
                                tmpdata = tmpdata
                            else:
                                data.loc[preindex:data[preindex:n][:-1].index[-1], fields] = data[preindex:n][:-1][fields] * float(series.loc[n, 'exer_forward_a']) + float(series.loc[n, 'exer_forward_b'])
                                tmpdata = tmpdata[:-1]
                        else:
                            tmp = data[preindex:n]
                            if tmp[n:].empty:
                                data.loc[preindex:n, fields] = data[preindex:n][fields] * float(series.loc[n, 'exer_forward_a']) + float(series.loc[n, 'exer_forward_b'])
                                tmp = tmp
                            else:
                                data.loc[preindex:data[preindex:n][:-1].index[-1], fields] = data[preindex:n][:-1][fields] * float(series.loc[n, 'exer_forward_a']) + float(series.loc[n, 'exer_forward_b'])
                                tmp = tmp[:-1]
                            tmpdata = tmpdata.append(tmp)
                if preindex != n:
                    preindex = n
            if preindex:
                tmpdata = tmpdata.append(data[preindex:])
            if tmpdata is not None:
                data = tmpdata
            return data
    def change_his_to_backward(self, security, data, exrights_data, start, end):
        if len(data) == 0:
            return data
        else:
            firstdate = list(data.index)[0].tz_localize(None).to_pydatetime().strftime('%Y%m%d')
            if start != firstdate:
                start = firstdate
            if len(start) > 8:
                start = start[:8]
            if len(end) > 8:
                end = end[:8]
            startDateIndex = qdt.datetime.strptime(start, '%Y%m%d').strftime('%Y-%m-%d 00:00:00')
            endDateIndex = qdt.datetime.strptime(end, '%Y%m%d').strftime('%Y-%m-%d 00:00:00')
            fields = ['open', 'close', 'high', 'low', 'price']
            series = exrights_data[security]
            if series.empty:
                return data
            elif series[:endDateIndex].empty:
                return data
            elif startDateIndex == endDateIndex:
                n = list(series[:endDateIndex].index)[-1]
                data = data * float(series.loc[n, 'exer_backward_a']) + float(series.loc[n, 'exer_backward_b'])
                return data
            else:
                preindex = None
                tmpdata = None
                if len(series[:startDateIndex].index) > 1:
                    tmpstartindex = series[:startDateIndex].index[-1]
                else:
                    tmpstartindex = None
            if len(series[endDateIndex:].index) > 0:
                tmpendindex = series[endDateIndex:].index[0]
            else:
                tmpendindex = None
            for n in list(series[tmpstartindex:tmpendindex].index):
                if preindex is None:
                    tmpdata = data[:n][:-1]
                elif data[preindex:n].empty or list(data[preindex:n].index)[-1].tz_localize(None) != pandas.Timestamp(qdt.datetime.strptime(n, '%Y-%m-%d 00:00:00')):
                    break
                else:
                    data.loc[preindex:data[preindex:n][:-1].index[-1], fields] = data[preindex:n][:-1][fields] * float(series.loc[preindex, 'exer_backward_a']) + float(series.loc[preindex, 'exer_backward_b'])
                    tmpdata = tmpdata.append(data[preindex:n][:-1])
                if preindex != n:
                    preindex = n
            if preindex:
                data.loc[preindex:, fields] = data[preindex:][fields] * float(series.loc[preindex, 'exer_backward_a']) + float(series.loc[preindex, 'exer_backward_b'])
                tmpdata = tmpdata.append(data[preindex:])
            if tmpdata is not None:
                data = tmpdata
            return data
