    def get_stock_status(self, stocks, query_type='ST', query_date=None):
        result = {}
        date_today = qdt.datetime.now().strftime('%Y%m%d')
        if isinstance(query_date, str):
            query_date = query_date.replace('-', '')
        if query_date is None:
            query_date = qdt.datetime.now().strftime('%Y%m%d')
        if isinstance(stocks, str):
            stocks = [stocks]
        elif isinstance(stocks, list):
            stocks = stocks
        else:
            self.log.quote.info('暂只支持str或list类型股票数据')
            return result
        try:
            if query_date >= date_today:
                if query_type == 'ST':
                    return self.is_ST_stock_real(stocks)
                elif query_type == 'HALT':
                    return self.is_halt_stock_real(stocks)
                elif query_type == 'DELISTING':
                    return self.is_delisting_stock_real(stocks)
                elif query_type == 'DELISTING_SORTING':
                    return is_delisting_sorting_stock_real(stocks)
                else:
                    return result
            elif query_type == 'ST':
                return self.is_ST_stock(stocks, query_date)
            elif query_type == 'HALT':
                return self.is_halt_stock(stocks, query_date)
            elif query_type == 'DELISTING':
                return self.is_delisting_stock(stocks, query_date)
            else:
                return result
            return None
        except BaseException as e:
            system_log.error(get_traceback_message())
            raise e
    def filter_stock_by_status(self, stocks, filter_type=['ST', 'HALT', 'DELISTING'], query_date=None):
        result = []
        date_today = qdt.datetime.now().strftime('%Y%m%d')
        if isinstance(query_date, str):
            query_date = query_date.replace('-', '')
        if query_date is None:
            query_date = date_today
        if isinstance(stocks, str):
            stocks = [stocks]
        elif isinstance(stocks, list):
            stocks = stocks
        else:
            system_log.error('暂只支持str或list类型股票数据')
            return result
        if isinstance(filter_type, str):
            query_type = [filter_type]
        elif isinstance(filter_type, list):
            query_type = filter_type
        else:
            system_log.error('暂只支持str或list类型过滤类型')
            return result
        try:
            ST_result = {}
            HALT_result = {}
            DELISTING_result = {}
            DELISTING_SORTING_result = {}
            if query_date >= date_today:
                if 'ST' in query_type:
                    ST_result = self.is_ST_stock_real(stocks)
                if 'HALT' in query_type:
                    HALT_result = self.is_halt_stock_real(stocks)
                if 'DELISTING' in query_type:
                    DELISTING_result = self.is_delisting_stock_real(stocks)
                if 'DELISTING_SORTING' in query_type:
                    DELISTING_SORTING_result = is_delisting_sorting_stock_real(stocks)
            else:
                if 'ST' in query_type:
                    ST_result = self.is_ST_stock(stocks, query_date)
                if 'HALT' in query_type:
                    HALT_result = self.is_halt_stock(stocks, query_date)
                if 'DELISTING' in query_type:
                    DELISTING_result = self.is_delisting_stock(stocks, query_date)
            for stock in stocks:
                if not ST_result.get(stock):
                    if HALT_result.get(stock):
                        continue
                    if DELISTING_result.get(stock):
                        continue
                    if DELISTING_SORTING_result.get(stock):
                        continue
                    result.append(stock)
            else:
                return result
            return None
        except BaseException:
            system_log.error(get_traceback_message())
            return result
