    def check_stock(self, s):
        if not isinstance(s, str):
            self.trade_log.error("请使用字符串表示标的代码，例如'600570.SS'")
        assert isinstance(s, str), "请使用字符串表示标的代码，例如'600570.SS'"
        if 11 >= len(s) >= 9:
            self.trade_log.error('请输入正确的标的代码')
        assert 11 >= len(s) >= 9, '请输入正确的标的代码'
        if s.split('.')[1] not in ('SS', 'SZ', 'CCFX', 'XDCE', 'XSGE', 'XZCE', 'XBHS'):
            self.trade_log.error("请输入标的代码以'SS','SZ','CCFX','XDCE','XSGE','XZCE'结尾")
        assert s.split('.')[1] in ('SS', 'SZ', 'CCFX', 'XDCE', 'XSGE', 'XZCE', 'XBHS'), "请输入标的代码以'SS','SZ','CCFX','XDCE','XSGE','XZCE', 'XBHS'结尾"
    def check_stocks(self, l):
        if isinstance(l, str):
            l = l.replace('.XSHE', '.SZ')
            l = l.replace('.XSHG', '.SS')
            return None
        elif isinstance(l, list) or isinstance(l, tuple):
            for s in l:
                s = s.replace('.XSHE', '.SZ')
                s = s.replace('.XSHG', '.SS')
        else:
            self.trade_log.error('您的输入有误 :%s' % l)
            assert False, '您的输入有误'
