    def _get_socket_message(self, params, address, context=None, socket=None, init=False):
        if context is None:
            context = zmq.Context()
        if socket is None:
            socket = context.socket(zmq.REQ)
            socket.setsockopt(zmq.LINGER, 0)
            socket.setsockopt(zmq.RCVTIMEO, 30000)
        elif not init:
            socket.close()
            socket = context.socket(zmq.REQ)
            socket.setsockopt(zmq.LINGER, 0)
            socket.setsockopt(zmq.RCVTIMEO, 30000)
        socket.connect(address)
        self.log.quote.debug('----通过zmq获取实时数据，具体参数为：%s...' % params[:50])
        socket.send_string(params)
        message = socket.recv()
        self.log.quote.debug('----获取实时数据应答包返回')
        socket.close()
        context.term()
        return (message, context, socket)
    def api_get_from_zeromq(self, params):
        context = zmq.Context()
        socket = context.socket(zmq.REQ)
        socket.setsockopt(zmq.LINGER, 0)
        socket.setsockopt(zmq.RCVTIMEO, 30000)
        try:
            universe = eval(params)[1:][0]
            universe = universe if isinstance(universe, str) else universe[0]
        except Exception as e:
            self.log.quote.debug('universe解析异常'.format(e))
            system_log.debug('universe解析异常'.format(e))
            universe = None
        first_address = address = self.get_remote_address(universe, 'req')
        try:
            message, context, socket = self._get_socket_message(params, address, context, socket, init=True)
        except BaseException:
            self.log.quote.error('zeromq与服务端{}建立链接失败，请求数据异常'.format(address))
            system_log.error('zeromq与服务端{}建立链接失败，请求数据异常'.format(address))
            _connec = False
            address = self.get_remote_address(universe, 'req', _next_address=True)
            while first_address != address:
                try:
                    message, context, socket = self._get_socket_message(params, address, context, socket)
                    _connec = True
                except Exception as e:
                    self.log.quote.error('zeromq与服务端{}建立链接失败，请求数据异常'.format(address))
                    self.log.quote.error('zeromq与服务端建立链接失败，请求数据异常, 异常:{}'.format(e))
                    system_log.error('zeromq与服务端建立链接失败，请求数据异常, 异常:{}'.format(e))
                    address = self.get_remote_address(universe, 'req', _next_address=True)
            else:
                if not _connec:
                    self.log.quote.error('----zeromq与服务端建立链接失败，请求数据异常')
                    system_log.error('----zeromq与服务端建立链接失败，请求数据异常')
                    return (None, 1)
                else:
                    try:
                        message = eval(message.decode())
                        return (message, 0)
                    except BaseException:
                        self.log.quote.error('----eval转化数据异常，参数为:%s...' % params[:50])
                        system_log.error('----eval转化数据异常，参数为:%s...' % params[:50])
                        self.log.quote.error('----数据内容：' + str(message))
                        system_log.error('----数据内容：' + str(message))
                        return (None, 1)
                    self.log.quote.warning('----zeromq获取数据为空，参数为:%s...' % params[:50])
                    system_log.debug('----zeromq获取数据为空，参数为:%s...' % params[:50])
                    return (None, -1)
                if message and len(message) > 0:
                    pass
    def api_get_from_multi_zeromq(self, params):
        stockContext = zmq.Context()
        stockSocket = stockContext.socket(zmq.REQ)
        stockSocket.setsockopt(zmq.LINGER, 0)
        stockSocket.setsockopt(zmq.RCVTIMEO, 30000)
        futureContext = zmq.Context()
        futureSocket = futureContext.socket(zmq.REQ)
        futureSocket.setsockopt(zmq.LINGER, 0)
        futureSocket.setsockopt(zmq.RCVTIMEO, 30000)
        universe = eval(params)[1:]
        tag = eval(params)[0]
        stockParams = [tag]
        futureParams = [tag]
        for stock in universe:
            security_type = check_stock_or_future(stock)
            if security_type == 'stock':
                stockParams.append(stock)
                continue
            elif security_type == 'future':
                futureParams.append(stock)
        if len(stockParams) > 1:
            first_stockAddress = stockAddress = self.get_remote_address(stockParams[1], 'req')
            try:
                stockMessage, stockContext, stockSocket = self._get_socket_message(str(stockParams), stockAddress, stockContext, stockSocket, init=True)
            except BaseException:
                self.log.quote.error('zeromq与服务端{}建立链接失败，请求数据异常'.format(stockAddress))
                _connec = False
                stockAddress = self.get_remote_address(stockParams[1], 'req', _next_address=True)
                while first_stockAddress != stockAddress:
                    try:
                        stockMessage, stockContext, stockSocket = self._get_socket_message(str(stockParams), stockAddress, stockContext, stockSocket)
                        _connec = True
                    except Exception as e:
                        self.log.quote.error('zeromq与服务端{}建立链接失败，请求数据异常'.format(stockAddress))
                        self.log.quote.error('zeromq与服务端建立链接失败，请求数据异常, 异常:{}'.format(e))
                        stockAddress = self.get_remote_address(stockParams[1], 'req', _next_address=True)
                else:
                    if not _connec:
                        self.log.quote.error('----zeromq与服务端建立链接失败，请求数据异常')
                        return (None, 1)
                    if len(futureParams) > 1:
                        first_futureAddress = futureAddress = self.get_remote_address(futureParams[1], 'req')
                        try:
                            futureMessage, futureContext, futureSocket = self._get_socket_message(str(futureParams), futureAddress, futureContext, futureSocket, init=True)
                        except BaseException:
                            self.log.quote.error('zeromq与服务端{}建立链接失败，请求数据异常'.format(futureAddress))
                            _connec = False
                            futureAddress = self.get_remote_address(futureParams[1], 'req', _next_address=True)
                            while first_futureAddress != futureAddress:
                                try:
                                    futureMessage, futureContext, futureSocket = self._get_socket_message(str(futureParams), futureAddress, futureContext, futureSocket)
                                    _connec = True
                                except Exception as e:
                                    self.log.quote.error('zeromq与服务端{}建立链接失败，请求数据异常'.format(futureAddress))
                                    self.log.quote.error('zeromq与服务端建立链接失败，请求数据异常, 异常:{}'.format(e))
                                    futureAddress = self.get_remote_address(futureParams[1], 'req', _next_address=True)
                            else:
                                if not _connec:
                                    self.log.quote.error('----zeromq与服务端建立链接失败，请求数据异常')
                                    return (None, 1)
                                else:
                                    stockDict = {}
                                    futureDict = {}
                                    multiMessage = {}
                                    if len(stockParams) > 1:
                                        try:
                                            stockDict = eval(stockMessage.decode())
                                            if tag == 'real':
                                                stockDict = stockDict.get('data').get('snapshot')
                                                del stockDict['fields']
                                        except BaseException:
                                            self.log.quote.error('----eval转化股票数据异常，参数为:%s...' % stockParams[:50])
                                            self.log.quote.error('----股票数据内容：' + str(stockDict))
                                            return (None, 1)
                                    if len(futureParams) > 1:
                                        try:
                                            futureDict = eval(futureMessage.decode())
                                            if tag == 'real':
                                                futureDict = futureDict.get('data').get('snapshot')
                                                del futureDict['fields']
                                        except BaseException:
                                            self.log.quote.error('----eval转化期货数据异常，参数为:%s...' % futureParams[:50])
                                            self.log.quote.error('----期货数据内容：' + str(futureDict))
                                            return (None, 1)
                                    multiMessage = dict(stockDict, **(futureDict))
                                    if tag == 'real':
                                        multiMessage['fields'] = ['data_timestamp', 'open_px', 'last_px', 'high_px', 'low_px', 'business_amount', 'business_balance']
                                        multiMessage = {'data': {'snapshot': multiMessage}}
                                    if len(multiMessage) == 0:
                                        self.log.quote.warning('----zeromq获取数据为空，参数为:%s...' % params[:50])
                                        return (None, -1)
                                    else:
                                        return (multiMessage, 0)
    def get_remote_address(self, universe, address_type='req', individual=False, _next_address=False):
        if individual:
            address = self.L2StockREPAddress if address_type == 'req' else self.L2StockPUBAddress
        else:
            address = self.StockREPAddress if address_type == 'req' else self.StockPUBAddress
        return self._get_valid_address(address, _next_address)
