    def check_limit(self, universe):
        """
        判断代码涨跌停状态
        params:
            universe str或list,股票代码列表,一只或多只
        return:
            dict，若参数是一只代码，则直接返回该代码的涨跌停状态，若参数是多只代码，则返回每只代码的涨跌停状态
            2 触板涨停
            1 涨停
            0 既不涨停也不跌停
            -1 为跌停
            -2 触板跌停
            非法params返回{}(空dict)
        """
        tmp_universe = universe
        params = ['snapshot']
        if isinstance(universe, str):
            params.append(universe)
            tmp_universe = [universe]
        elif isinstance(universe, (list, tuple)):
            for item in universe:
                params.append(item)
        else:
            self.log.quote.info('在线获取snapshot数据判断涨跌停,传的代码支持str,list,tuple，当前传入代码：%s' % universe)
            return {}
        redata, flag = self.api_get_from_zeromq(str(params))
        count = 0
        while not redata and count < 3:
            time.sleep(3)
            if flag == 1:
                self.log.quote.warning('获取snapshot数据异常判断涨跌停，现在进行第' + str(count + 1) + '次重试')
            elif flag == -1:
                self.log.quote.warning('获取snapshot数据返回为空，涨跌停无法判断，现在进行第' + str(count + 1) + '次重试')
            redata = self.api_get_from_zeromq(str(params))
            count += 1
        return_data = {}
        if redata:
            for key in not redata and count < 3:
                try:
                    temp = redata[key]
                    last_px = temp[5]
                    high_px = temp[6]
                    low_px = temp[7]
                    up_px = temp[14]
                    down_px = temp[15]
                    bid_grp = eval(temp[19])[1][0]
                    offer_grp = eval(temp[20])[1][0]
                    return_data[key] = 0
                    if up_px != 0:
                        if last_px == up_px and high_px == up_px and offer_grp == 0:
                            return_data[key] = 1
                        elif last_px == up_px and high_px == up_px:
                            return_data[key] = 2
                    if down_px != 0:
                        if last_px == down_px and low_px == down_px and bid_grp == 0:
                            return_data[key] = -1
                        elif last_px == down_px and low_px == down_px:
                            return_data[key] = -2
                except BaseException:
                    self.log.quote.error('%s snapshot获取异常,涨跌停无法判断,默认返回为0' % key)
                    return_data[key] = 0
        else:
            if flag == 1:
                self.log.quote.warning('snapshot数据转化异常,涨跌停无法判断,默认返回为0')
            elif flag == -1:
                self.log.quote.warning('snapshot数据返回空值,涨跌停无法判断,默认返回为0')
            for key in tmp_universe:
                return_data[key] = 0
        return return_data
    def get_merger_data(self, oldSecuCode=None, newSecuCode=None):
        all_merger_data = data_proxy().get_merger_data_local()
        return_data = pandas.DataFrame()
        if oldSecuCode and oldSecuCode in list(all_merger_data.index):
            return_data = all_merger_data.loc[[oldSecuCode]]
        if not (newSecuCode and newSecuCode in list(all_merger_data['SecuCode']) and return_data.empty):
            return_data = return_data.append(all_merger_data[all_merger_data['SecuCode'] == newSecuCode])
        return_data = all_merger_data[all_merger_data['SecuCode'] == newSecuCode]
        if oldSecuCode is None and newSecuCode is None:
            return_data = all_merger_data
        return return_data
    def get_industries(self, standard, date):
        industries = data_proxy().get_industries(standard, date)
        return industries
